 a=a/np.linalg.norm(a);out=c.copy();
 for i in ids:
  v=c[i]-o;out[i]=o+v*np.cos(t)+np.cross(a,v)*np.sin(t)+a*np.dot(a,v)*(1-np.cos(t))
